import ast
from pathlib import Path
import sys


ROOT = Path(__file__).resolve().parents[1]
EXCLUDED_DIRECTORIES = {".git", ".tmp", ".venv", "venv", "__pycache__", "generated"}


def private_module(name):
    return name == "payments._ledger" or name.startswith("payments._ledger.")


def private_accesses(tree):
    payment_names = {
        alias.asname or "payments"
        for node in ast.walk(tree)
        if isinstance(node, ast.Import)
        for alias in node.names
        if alias.name == "payments"
    }
    lines = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            if any(private_module(alias.name) for alias in node.names):
                lines.add(node.lineno)
        elif isinstance(node, ast.ImportFrom) and node.level == 0:
            if private_module(node.module or "") or (
                node.module == "payments"
                and any(alias.name == "_ledger" for alias in node.names)
            ):
                lines.add(node.lineno)
        elif isinstance(node, ast.Attribute):
            if (
                node.attr == "_ledger"
                and isinstance(node.value, ast.Name)
                and node.value.id in payment_names
            ):
                lines.add(node.lineno)
    return sorted(lines)


def main():
    failures = []
    checked = 0
    for path in sorted(ROOT.rglob("*.py")):
        relative = path.relative_to(ROOT)
        if relative.parts[0] == "payments" or EXCLUDED_DIRECTORIES.intersection(relative.parts[:-1]):
            continue
        checked += 1
        try:
            tree = ast.parse(path.read_text(), filename=str(relative))
        except (OSError, SyntaxError, UnicodeError) as error:
            failures.append(f"{relative}: cannot check Python source: {error}")
            continue
        for line in private_accesses(tree):
            failures.append(f"{relative}:{line}: payments._ledger is private; call payments.charge")
    print(f"Checked {checked} caller files")
    for failure in failures:
        print(failure, file=sys.stderr)
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())

