import ast
from pathlib import Path
import sys

root = Path(__file__).resolve().parents[1]
failures = []
checked = 0

for path in sorted((root / "app").rglob("*.py")):
    relative_path = path.relative_to(root)
    if "generated" in relative_path.parts:
        continue
    checked += 1
    for node in ast.walk(ast.parse(path.read_text(), filename=str(relative_path))):
        if isinstance(node, ast.Import):
            names = [alias.name for alias in node.names]
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ""
            names = [module, *(f"{module}.{alias.name}" for alias in node.names)]
        else:
            continue
        if any(name == "payments._ledger" or name.startswith("payments._ledger.") for name in names):
            failures.append(
                f"{relative_path}:{node.lineno}: payments._ledger is private; call payments.charge"
            )

print(f"Checked {checked} caller files")
if checked == 0:
    failures.append("No caller files found in app; the payments boundary was not checked")
for failure in failures:
    print(failure, file=sys.stderr)
sys.exit(1 if failures else 0)

